import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadIlahiData(){const e=readFileSync(resolve(__dirname,"../../akbar-ilahi-coinage-explorer/ilahi-data.js"),"utf-8");return new Function(e+"\nreturn { AKBAR_INFO, COIN_TYPES, ILAHI_MONTHS, INSCRIPTION_HOTSPOTS, TIMELINE_EVENTS, REFERENCES };")()}describe("Akbar's Ilahi Coinage Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadIlahiData()}),describe("AKBAR_INFO metadata",()=>{it("contains correct Akbar Ilahi coinage attributes",()=>{expect(e.AKBAR_INFO.id).toBe("akbar-ilahi-coinage"),expect(e.AKBAR_INFO.title).toContain("Akbar"),expect(e.AKBAR_INFO.motto).toContain("Allahu Akbar"),expect(e.AKBAR_INFO.reformYear).toContain("1585")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.AKBAR_INFO.quickStats)).toBe(!0),expect(e.AKBAR_INFO.quickStats.length).toBe(6)})}),describe("COIN_TYPES & ILAHI_MONTHS",()=>{it("contains representative coins and all 12 solar Ilahi months",()=>{expect(Array.isArray(e.COIN_TYPES)).toBe(!0),expect(e.COIN_TYPES.length).toBeGreaterThanOrEqual(3),expect(Array.isArray(e.ILAHI_MONTHS)).toBe(!0),expect(e.ILAHI_MONTHS.length).toBe(12);const t=e.ILAHI_MONTHS.find(e=>"Farwardin"===e.name);expect(t).toBeDefined()})}),describe("INSCRIPTION_HOTSPOTS & TIMELINE",()=>{it("contains inscription hotspots and historical timeline",()=>{expect(Array.isArray(e.INSCRIPTION_HOTSPOTS)).toBe(!0),expect(e.INSCRIPTION_HOTSPOTS.length).toBeGreaterThanOrEqual(3),expect(Array.isArray(e.TIMELINE_EVENTS)).toBe(!0),expect(e.TIMELINE_EVENTS.length).toBeGreaterThanOrEqual(4)})}),describe("REFERENCES",()=>{it("has non-empty references list",()=>{expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});